+        cells_x: top.cells_x,
+        cells_y: top.cells_y,
+        cell: top.cell,
+        tol,
+        dev,
+        rest_cells: top.rest_cells + bot.rest_cells,
+        gouge_cells: top.gouge_cells + bot.gouge_cells,
+        rest_volume: top.rest_volume + bot.rest_volume,
+        gouge_volume: top.gouge_volume + bot.gouge_volume,
+        max_rest,
+        max_gouge,
+        max_rest_at,
+        max_gouge_at,
+    }
+}

